export default (rows, ctx) => {
  const answer = ctx.call({
    url: 'https://api.unusualwhales.com/api/option-trades/flow-alerts?limit=100',
    headers: { Authorization: 'Bearer {{env:UNUSUAL_WHALES_API_KEY}}', Accept: 'application/json' }
  });
  if (answer.status !== 200) throw new Error('unusual whales said ' + answer.status);
  return JSON.parse(answer.body).data.map((a) => ({
    alert_id: String(a.id ?? ''),
    ticker: String(a.ticker ?? ''),
    kind: String(a.type ?? ''),
    strike: String(a.strike ?? ''),
    expiry: String(a.expiry ?? ''),
    premium: String(a.total_premium ?? '0'),
    ask_side_premium: String(a.total_ask_side_prem ?? '0'),
    bid_side_premium: String(a.total_bid_side_prem ?? '0'),
    volume_oi_ratio: String(a.volume_oi_ratio ?? '0'),
    alert_rule: String(a.alert_rule ?? ''),
    sweep: a.has_sweep ? 'yes' : 'no',
    underlying_price: String(a.underlying_price ?? '0'),
    observed_at: String(a.created_at ?? '')
  }));
}
